cd /mnt/session/uploads; python3 - <<'E'
import json,collections
rows=[json.loads(l) for l in open('app.log') if l.startswith('{')]
print(collections.Counter((r['level']) for r in rows))
# non-routine msgs
c=collections.Counter()
for r in rows:
    m=r['msg']
    if r['level'] in('WARN','ERROR','FATAL') : c[(r['service'],r['level'],m[:90])]+=1
for k,v in c.most_common(40):print(v,k)
# checkout per-minute: queries per request, latency
by=collections.defaultdict(lambda:[0,[],0])
q=collections.Counter()
for r in rows:
    if r['service']!='checkout':continue
    if r['msg'].startswith('db_query'): q[r['request_id']]+=1
for r in rows:
    if r['service']=='checkout' and r['msg'].startswith('request_end') and 'latency_ms' in r:
        m=r['ts'][11:16]; by[m][1].append((r['latency_ms'],q[r['request_id']]))
for m in sorted(by):
    l=by[m][1]
    if m>='14:06' and (m<'14:12' or m>'14:26'): print(m,len(l),sum(a for a,b in l)/len(l),sum(b for a,b in l)/len(l))
E

cd /mnt/session/uploads; grep -n "rollback\|deploy\|restart\|start" app.log | grep -v request_start | head; python3 - <<'E'
import json,collections
rows=[json.loads(l) for l in open('app.log') if l.startswith('{')]
for r in rows:
    if r['service']=='checkout' and '14:29:0'<=r['ts'][11:19]<='14:30:10' and r['level']!='DEBUG' or 'rollback' in r['msg'] : print(r)
# first pool errors
print([r['ts'] for r in rows if 'pool' in r['msg']][:3])
# req rate and queries/req per host and per path, before/after
q=collections.Counter(); 
for r in rows:
    if r['service']=='checkout' and r['msg'].startswith('db_query'): q[r['request_id']]+=1
import statistics
for lo,hi in [('14:10','14:26'),('14:26','14:30'),('14:30','14:40')]:
    s=[(r['path'] if 'path' in r else r['msg'].split('path=')[1].split()[0], q[r['request_id']]) for r in rows if r['service']=='checkout' and r['msg'].startswith('request_end') and lo<=r['ts'][11:16]<hi]
    print(lo,len(s),collections.Counter(p for p,_ in s), statistics.mean(n for _,n in s))
# duration of db_query before vs after
for lo,hi in [('14:10','14:30'),('14:30','14:40')]:
    d=[r['duration_ms'] for r in rows if r['service']=='checkout' and r['msg'].startswith('db_query') and lo<=r['ts'][11:16]<hi and 'duration_ms' in r]
    print(lo,len(d),statistics.mean(d))
